#include "legacy_highfreq_page.hpp"
#include "chart.hpp"
#include "detail_disclosure.hpp"
#include <QtWidgets>
LegacyHighFrequencyPage::LegacyHighFrequencyPage(QString archive,QString refs,QWidget*p):QWidget(p),store(std::move(archive),std::move(refs)){
 setObjectName("legacyHighFrequencyPage");workers.setMaxThreadCount(1);auto layout=new QVBoxLayout(this);auto notice=new QLabel("旧版5秒 / 30秒历史 · 只读原日期与桶尾。成交量空值、未观测时段保留；不补今日、不重算行情。身份依据为原快照名称与明确证券目录；不足时仅列范围。",this);notice->setWordWrap(true);addDataDetails(layout,notice,"secondsDataDetails");auto row=new QHBoxLayout;security=new QComboBox(this);security->setObjectName("legacyHighFrequencySecurity");security->setMinimumContentsLength(20);date=new QComboBox(this);date->setObjectName("legacyHighFrequencyDate");date->setMinimumContentsLength(19);date->setMinimumWidth(205);interval=new QComboBox(this);interval->setObjectName("legacyHighFrequencyInterval");interval->addItem("原5秒桶",5);interval->addItem("原30秒桶",30);open=new QPushButton("在看盘主图打开所选历史",this);open->setObjectName("legacyHighFrequencyOpenMain");row->addWidget(security,1);row->addWidget(date);row->addWidget(interval);row->addWidget(open);layout->addLayout(row);status=new QLabel(this);status->setObjectName("legacyHighFrequencyStatus");status->setWordWrap(true);status->setTextFormat(Qt::PlainText);layout->addWidget(status);preview=new Chart(this);preview->setObjectName("legacyHighFrequencyChart");preview->overlay=false;preview->showNine=false;layout->addWidget(preview,2);original=new QPlainTextEdit(this);original->setObjectName("legacyHighFrequencyOriginal");original->setReadOnly(true);original->setMaximumHeight(180);addDataDetails(layout,original,"secondsOriginalDetails");
 connect(security,&QComboBox::currentIndexChanged,this,[this]{if(!filling)chooseSecurity();});connect(interval,&QComboBox::currentIndexChanged,this,[this]{if(!filling)chooseSecurity();});connect(date,&QComboBox::currentIndexChanged,this,[this]{if(!filling)loadSelection();});connect(open,&QPushButton::clicked,this,[this]{if(!isVisible()||window()->isMinimized()||busy||packet.isEmpty())return;auto current=security->currentData().toJsonObject();if(current["id"]!=packet["id"]||date->currentData()!=packet["tradingDate"].toString()||interval->currentData().toInt()!=packet["intervalSeconds"].toInt())return;emit openOnMainChart(packet);});controls();
}
LegacyHighFrequencyPage::~LegacyHighFrequencyPage(){cancel();workers.waitForDone();}
void LegacyHighFrequencyPage::controls(){open->setEnabled(isVisible()&&!busy&&!packet.isEmpty());}
void LegacyHighFrequencyPage::cancel(){stopped->store(true);++generation;busy=false;controls();}
void LegacyHighFrequencyPage::work(std::function<QJsonObject(legacyHighFrequency::Cancel)> job,std::function<void(QJsonObject)> done){cancel();stopped=std::make_shared<std::atomic_bool>(false);auto flag=stopped;auto token=generation;busy=true;controls();QPointer<LegacyHighFrequencyPage> guard=this;workers.start([guard,flag,token,job=std::move(job),done=std::move(done)]{QJsonObject value;QString error;try{value=job([flag]{return flag->load();});}catch(const std::exception&e){error=QString::fromUtf8(e.what());}if(!guard)return;QMetaObject::invokeMethod(guard,[guard,flag,token,value,error,done]{if(!guard||flag->load()||guard->generation!=token||!guard->isVisible())return;guard->busy=false;if(error.isEmpty())done(value);else{guard->packet={};guard->preview->setSeries({}, {},true);guard->status->setText(error);}guard->controls();},Qt::QueuedConnection);});}
void LegacyHighFrequencyPage::loadInventory(){packet={};status->setText("正在读取证券与历史日期…");auto reader=store;work([reader](auto c){return reader.inventory(c);},[this](QJsonObject value){
 catalog=value;filling=true;security->clear();
 for(auto v:catalog["rows"].toArray()){auto r=v.toObject();bool bars=!r["5s"].toArray().isEmpty()||!r["30s"].toArray().isEmpty();security->addItem(r["code"].toString()+" · "+r["name"].toString("名称缺失")+(r["canOpen"].toBool()?QString():" · 身份不足")+(bars?QString():" · 无高频历史"),r);}
 const auto expectedId=property("requestedHistoryIdentity").toString();
 int selected=restoreCode.isEmpty()&&expectedId.isEmpty()?0:-1;
 for(int i=0;i<security->count();++i){auto row=security->itemData(i).toJsonObject();if(expectedId.isEmpty()?row["code"]==restoreCode:row["id"]==expectedId)selected=i;}
 security->setCurrentIndex(selected);filling=false;setProperty("requestedHistoryIdentity",{});
 if(selected<0){date->clear();packet={};preview->setSeries({}, {},true);status->setText("所选证券暂无可核验的秒级历史；未替换成同代码的其他证券。");controls();return;}
 chooseSecurity();
 });}
void LegacyHighFrequencyPage::chooseSecurity(){cancel();packet={};preview->setSeries({}, {},true);auto r=security->currentData().toJsonObject();auto old=date->currentData().toString();filling=true;date->clear();auto dates=r[QString::number(interval->currentData().toInt())+"s"].toArray();for(int i=dates.size()-1;i>=0;--i){auto d=dates[i].toObject();date->addItem(d["date"].toString()+" · "+QString::number(d["rows"].toInt())+"条",d["date"].toString());}int wanted=date->findData(restoreDate.isEmpty()?old:restoreDate);if(wanted>=0)date->setCurrentIndex(wanted);restoreDate.clear();filling=false;original->setPlainText(QString::fromUtf8(QJsonDocument(r).toJson(QJsonDocument::Indented)));if(r["canOpen"]!=true){status->setText(r["identityReason"].toString()+QString("；原高频代码%1，可绑定%2，身份不足%3。原记录未改。").arg(catalog["barCodeCount"].toInt()).arg(catalog["resolvedBarCodeCount"].toInt()).arg(catalog["unresolvedBarCodeCount"].toInt()));controls();return;}if(date->count()==0){status->setText("此证券没有所选粒度的原日期记录；未显示其他证券或今日数据。");controls();return;}loadSelection();}
void LegacyHighFrequencyPage::loadSelection(){cancel();packet={};preview->setSeries({}, {},true);auto identity=security->currentData().toJsonObject();if(identity["canOpen"]!=true||date->currentIndex()<0){controls();return;}QString id=identity["id"].toString(),day=date->currentData().toString();int seconds=interval->currentData().toInt();auto reader=store;status->setText("正在只读原日期 · "+id+" · "+day);work([reader,id,day,seconds](auto c){return reader.load(id,day,seconds,c);},[this,id,day,seconds](QJsonObject value){if(security->currentData().toJsonObject()["id"]!=id||date->currentData().toString()!=day||interval->currentData().toInt()!=seconds)return;packet=value;legacyHighFrequency::showOnChart(preview,packet);status->setText(legacyHighFrequency::caption(packet)+QString("；身份不足代码%1个，原目录可查。").arg(catalog["unresolvedBarCodeCount"].toInt()));original->setPlainText(QString::fromUtf8(QJsonDocument(packet).toJson(QJsonDocument::Indented)));});}
QJsonObject LegacyHighFrequencyPage::saveState()const{return {{"schema","native-legacy-highfreq-ui/v1"},{"code",security->currentData().toJsonObject()["code"]},{"date",date->currentData().toString()},{"seconds",interval->currentData().toInt()}};}
void LegacyHighFrequencyPage::restoreState(QJsonObject s){if(s["schema"]!="native-legacy-highfreq-ui/v1")return;cancel();packet={};preview->setSeries({}, {},true);restoreCode=s["code"].toString();restoreDate=s["date"].toString();setProperty("requestedHistoryIdentity",s["id"].toString());filling=true;date->clear();interval->setCurrentIndex(s["seconds"].toInt()==30?1:0);filling=false;if(isVisible())loadInventory();}
QJsonObject LegacyHighFrequencyPage::sourceEvidence()const{QJsonObject result{{"busy",busy},{"inventory",catalog},{"packet",packet}};return result;}
void LegacyHighFrequencyPage::hideEvent(QHideEvent*e){cancel();QWidget::hideEvent(e);}
void LegacyHighFrequencyPage::showEvent(QShowEvent*e){QWidget::showEvent(e);if(catalog.isEmpty())loadInventory();else chooseSecurity();}
